import React, { useState } from 'react';
import axios from 'axios';
const { google } = require('google-auth-library'); // Importa la librería de Google

const GoogleWalletIntegration = () => {
  const [ticketUrl, setTicketUrl] = useState('');

  const createEventTicket = async () => {
    const serviceAccount = require('./google.json'); // Asegúrate de que el archivo esté en src/
    const issuerId = '3388000000022860703';
    const classId = 'HDI12345';
    const objectId = 'TEST-HDIV02';

    const eventTicketClass = {
      id: `${issuerId}.${classId}`,
      issuerName: 'Your Event Name',
      reviewStatus: 'UNDER_REVIEW',
      eventName: {
        defaultValue: {
          language: 'en',
          value: 'Your Event Name',
        },
      },
    };

    const eventTicketObject = {
      id: `${issuerId}.${objectId}`,
      classId: `${issuerId}.${classId}`,
      state: 'ACTIVE',
      barcode: {
        type: 'QR_CODE',
        value: '1234567890',
      },
      seatInfo: {
        seat: {
          defaultValue: {
            language: 'en',
            value: 'A1',
          },
        },
      },
    };

    try {
      const authClient = new google.auth.JWT({
        email: serviceAccount.client_email,
        key: serviceAccount.private_key,
        scopes: ['https://www.googleapis.com/auth/wallet_object.issuer'],
      });

      const tokens = await authClient.authorize();

      const response = await axios.post(
        `https://walletobjects.googleapis.com/walletobjects/v1/eventTicketClass`,
        eventTicketClass,
        {
          headers: {
            Authorization: `Bearer ${tokens.access_token}`,
            'Content-Type': 'application/json',
          },
        }
      );

      const response2 = await axios.post(
        `https://walletobjects.googleapis.com/walletobjects/v1/eventTicketObject`,
        eventTicketObject,
        {
          headers: {
            Authorization: `Bearer ${tokens.access_token}`,
            'Content-Type': 'application/json',
          },
        }
      );

      setTicketUrl(response2.data.alternateLink);
    } catch (error) {
      console.error('Error creating event ticket:', error);
    }
  };

  return (
    <div>
      <h1>Google Wallet Event Ticket Integration</h1>
      <button onClick={createEventTicket}>Create Event Ticket</button>
      {ticketUrl && (
        <div>
          <p>Ticket created successfully!</p>
          <a href={ticketUrl} target="_blank" rel="noopener noreferrer">
            View Ticket
          </a>
        </div>
      )}
    </div>
  );
};

export default GoogleWalletIntegration;
